import { Button } from "@mui/material";
import React, { useEffect, useState } from "react";
import data from "../data.json";
import feedback from "../feeback.json";
import { DragDropContext, Draggable, Droppable } from "react-beautiful-dnd";
import Swal from "sweetalert2";
// import bg from "../image/posbg.jpg";
import { useNavigate } from "react-router-dom";

const MainpageMidcontent = () => {
  let [skipCount, setSkipCount] = useState(0);
  let [randomIndex, setRandomIndex] = useState(0);
  let [randomNoArray, setRandomNoArray] = useState([0]);
  let [tasks, setTasks] = useState([]);
  let [columns, setColumns] = useState({});
  let navigate = useNavigate();
  let [disableNext, setDisableNext] = useState(true);

  useEffect(() => {
    const initializeTasks = () => {
      if (!data[randomIndex].sentenceArray) return;
      const newTasks = data[randomIndex].sentenceArray.map((item, index) => ({
        id: `${index}`,
        content: item,
      }));
      setTasks(newTasks);
      setColumns({
        list: {
          name: "List",
          items: newTasks,
        },
        noun: {
          name: "Noun",
          items: [],
        },
        pronoun: {
          name: "Pronoun",
          items: [],
        },
        verb: {
          name: "Verb",
          items: [],
        },
        adjective: {
          name: "Adjective",
          items: [],
        },
        adverb: {
          name: "Adverb",
          items: [],
        },
        preposition: {
          name: "Preposition",
          items: [],
        },
        conjunction: {
          name: "Conjunction",
          items: [],
        },
        interjection: {
          name: "Interjection",
          items: [],
        },
        article: {
          name: "Article",
          items: [],
        },
      });
    };

    initializeTasks();
  }, [randomIndex]);

  useEffect(() => {
    const jsonArrays = {
      noun: data[randomIndex].noun,
      pronoun: data[randomIndex].pronoun,
      verb: data[randomIndex].verb,
      adjective: data[randomIndex].adjective,
      adverb: data[randomIndex].adverb,
      preposition: data[randomIndex].preposition,
      conjunction: data[randomIndex].conjunction,
      interjection: data[randomIndex].interjection,
      article: data[randomIndex].article,
    };
    const checkAndUpdateBorders = (columns, jsonArrays) => {
      const categories = Object.keys(columns);

      categories.forEach((category) => {
        if (category === "list") return;
        const jsonArrayNormalized =
          jsonArrays[category]?.map((word) => word.trim().toLowerCase()) || [];

        columns[category].items.forEach((item) => {
          const wordNormalized = item.content.trim().toLowerCase();
          const element = document.getElementById(`${item.content}`); // Use item.content as the id
          if (element) {
            if (jsonArrayNormalized.includes(wordNormalized)) {
              element.style.border = "2px solid green"; // Correct category
            } else {
              element.style.border = "2px solid red"; // Incorrect category
            }
          }
        });
      });
    };
    checkAndUpdateBorders(columns, jsonArrays);
  }, [columns]);

  const onDragEnd = (result, columns, setColumns) => {
    const { source, destination } = result;
    if (!destination) return;
    if (destination.droppableId === "list") return;
    const sourceColumn = columns[source.droppableId];
    const droppedWord = sourceColumn.items[source.index].content; // Get the dropped word

    if (source.droppableId !== destination.droppableId) {
      const sourceColumn = columns[source.droppableId];
      const destColumn = columns[destination.droppableId];
      const sourceItems = [...sourceColumn.items];
      const destItems = [...destColumn.items];
      const [removed] = sourceItems.splice(source.index, 1);
      destItems.splice(destination.index, 0, removed);
      setColumns({
        ...columns,
        [source.droppableId]: {
          ...sourceColumn,
          items: sourceItems,
        },
        [destination.droppableId]: {
          ...destColumn,
          items: destItems,
        },
      });
    } else {
      const column = columns[source.droppableId];
      const copiedItems = [...column.items];
      const [removed] = copiedItems.splice(source.index, 1);
      copiedItems.splice(destination.index, 0, removed);
      setColumns({
        ...columns,
        [source.droppableId]: {
          ...column,
          items: copiedItems,
        },
      });
    }

    handleVerify(droppedWord, destination.droppableId);
  };

  const handleVerify = (droppedWord, droppableId) => {
    const categories = [
      "noun",
      "pronoun",
      "verb",
      "adjective",
      "adverb",
      "preposition",
      "conjunction",
      "interjection",
      "article",
    ];

    const jsonArrays = {
      noun: data[randomIndex].noun,
      pronoun: data[randomIndex].pronoun,
      verb: data[randomIndex].verb,
      adjective: data[randomIndex].adjective,
      adverb: data[randomIndex].adverb,
      preposition: data[randomIndex].preposition,
      conjunction: data[randomIndex].conjunction,
      interjection: data[randomIndex].interjection,
      article: data[randomIndex].article,
    };

    const draggedArrays = categories.reduce((acc, category) => {
      if (columns[category] && columns[category].items) {
        acc[category] = columns[category].items.map((item) =>
          item.content.trim().toLowerCase()
        );
      } else {
        acc[category] = [];
      }
      return acc;
    }, {});

    categories.forEach((category) => {
      // Check for words that do not belong in the current category
      const jsonArrayNormalized =
        jsonArrays[category]?.map((word) => word.trim().toLowerCase()) || [];

      const draggedArrayNormalized = draggedArrays[category];

      const notInCategory = draggedArrayNormalized.filter(
        (item) => !jsonArrayNormalized.includes(item)
      );
      const inCategory = draggedArrayNormalized.filter((item) =>
        jsonArrayNormalized.includes(item)
      );

      notInCategory.forEach((item) => {
        const element = document.getElementById(`${item}`);
        if (element) element.style.border = "2px solid red";
      });

      inCategory.forEach((item) => {
        const element = document.getElementById(`${item}`);
        if (element) element.style.border = "2px solid green";
      });

      // Normalize dropped word
      const normalizedDroppedWord =
        typeof droppedWord === "string"
          ? droppedWord.trim().toLowerCase()
          : String(droppedWord).trim().toLowerCase();

      // Show alert if the dropped word is incorrect
      if (
        !jsonArrayNormalized.includes(normalizedDroppedWord) &&
        droppableId === category
      ) {
        Swal.fire({
          title: "Incorrect!",
          html: `
            "${droppedWord}" is not a ${category} word.<br/><br/>

            ${feedback[category.toLowerCase()].definition}
            <b>eg:</b> ${feedback[category.toLowerCase()].example}
          `,
          customClass: {
            title: "red-text",
            htmlContainer: "red-text",
          },
        });
      }
    });

    // Check if all categories match
    const allCategoriesMatch = categories.every((category) => {
      const normalizedDraggedArray = draggedArrays[category].sort();
      const normalizedJsonArray = jsonArrays[category]
        .map((item) => item.trim().toLowerCase())
        .sort();

      const isMatch =
        normalizedDraggedArray.length === normalizedJsonArray.length &&
        normalizedDraggedArray.every(
          (item, index) => item === normalizedJsonArray[index]
        );

      return isMatch;
    });

    if (allCategoriesMatch) {
      setDisableNext(false);
      Swal.fire({
        title: "Good job!",
        text: "You are correct!",
        customClass: {
          title: "green-text",
          htmlContainer: "green-text",
        },
      });
    }
  };

  const handleNext = () => {
    setDisableNext(true);
    const newRandomIndex = Math.floor(Math.random() * data.length);
    const newSentenceArray = data[newRandomIndex].sentenceArray;
    if (randomNoArray.length !== 5) {
      if (randomNoArray.includes(newRandomIndex)) {
        handleNext();
      } else {
        setRandomNoArray((prevState) => [...prevState, newRandomIndex]);
        setRandomIndex(newRandomIndex);
      }
    } else {
      Swal.fire({
        title: `You have successfully attempted ${
          5 - skipCount
        } out of 5 sentences!`,
        showClass: {
          popup: "animate__animated animate__fadeInDown",
        },
        hideClass: {
          popup: "animate__animated animate__fadeOutUp",
        },
        customClass: {
          title: "completeion-text",
          htmlContainer: "completeion-text",
        },
        confirmButtonText: "Restart",
      }).then((result) => {
        if (result.isConfirmed) {
          navigate("/");
        }
      });
    }
    // Get the new sentence array based on the new random index
    const newTasks = newSentenceArray.map((item, index) => ({
      id: `${index}`,
      content: item,
    }));

    // Clear the columns and update the tasks
    setColumns({
      list: {
        name: "List",
        items: newTasks,
      },
      noun: {
        name: "Noun",
        items: [],
      },
      pronoun: {
        name: "Pronoun",
        items: [],
      },
      verb: {
        name: "Verb",
        items: [],
      },
      adjective: {
        name: "Adjective",
        items: [],
      },
      adverb: {
        name: "Adverb",
        items: [],
      },
      preposition: {
        name: "Preposition",
        items: [],
      },
      conjunction: {
        name: "Conjunction",
        items: [],
      },
      interjection: {
        name: "Interjection",
        items: [],
      },
    });

    // Reset the tasks state
    setTasks(newTasks);
  };

  const handleSkip = () => {
    let newSkipCount = skipCount + 1;
    setSkipCount(newSkipCount);
    handleNext();
  };

  return (
    <div
      className="row d-flex scrollbar-primary"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            overflow: "auto",
            // background: "#FFFFFF 0% 0% no-repeat padding-box",
            // backgroundImage: `url(${bg})`,
            // backgroundSize: "cover", // Ensures the image covers the entire div
            // backgroundPosition: "center", // Centers the image
            // backgroundRepeat: "no-repeat", // Prevents the image from repeating
            height: "80vh",
            width: "95%",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "1%",
            overflowX: "hidden",
            margin: "5px",
          }}
        >
          {/* drag drop code starts here */}

          <div className="row justify-content-center">
            <DragDropContext
              onDragEnd={(result) => onDragEnd(result, columns, setColumns)}
            >
              {Object.entries(columns).map(([columnId, column], index) => {
                return (
                  <div
                    style={{
                      margin: columnId === "list" ? "" : "1%",
                      display: "flex",
                      justifyContent: "center",
                    }}
                    className={
                      columnId === "list"
                        ? ""
                        : "col-6 col-md-3 col-lg-2 col-sm-4"
                    }
                    key={columnId}
                  >
                    <Droppable droppableId={columnId} key={columnId}>
                      {(provided, snapshot) => {
                        return (
                          <div
                            {...provided.droppableProps}
                            ref={provided.innerRef}
                            style={{
                              padding: columnId === "list" ? "1%" : "5%",
                              background: snapshot.isDraggingOver
                                ? columnId == "list"
                                  ? ""
                                  : ""
                                : columnId == "list"
                                ? ""
                                : "",
                              border:
                                columnId === "list" ? "" : "1px solid #36638C",
                              borderRadius: columnId === "list" ? "" : "12px",
                              boxShadow:
                                columnId === "list"
                                  ? ""
                                  : "5px 10px 24px #00000029",
                              width: columnId === "list" ? "100%" : 200,
                              minHeight: columnId === "list" ? 50 : 200,
                              display: columnId === "list" ? "flex" : "",
                              flexWrap: columnId === "list" ? "wrap" : "",
                              justifyContent:
                                columnId === "list" ? "center" : "",
                            }}
                          >
                            <div
                              className="fw-bolder d-flex align-items-center justify-content-center"
                              style={{
                                color:
                                  columnId === "list" ? "#707070" : "#31506F",
                              }}
                            >
                              {columnId === "list" ? "Sentence:" : column.name}
                            </div>
                            <hr
                              style={{
                                marginTop: 0,
                                marginBottom: "8px",
                                color: "#31506F",
                              }}
                            />
                            {column.items.map((item, index) => {
                              return (
                                <Draggable
                                  key={item.id}
                                  draggableId={item.id}
                                  index={index}
                                >
                                  {(provided, snapshot) => {
                                    return (
                                      <div
                                        id={item.content}
                                        className="text-center"
                                        ref={provided.innerRef}
                                        {...provided.draggableProps}
                                        {...provided.dragHandleProps}
                                        style={{
                                          background:
                                            columnId === "list"
                                              ? "#FFD18B 0% 0% no-repeat padding-box"
                                              : "",
                                          border:
                                            columnId === "list"
                                              ? "1px solid #707070"
                                              : "",
                                          boxShadow: "0px 3px 6px #00000029",

                                          borderRadius: "7px",
                                          userSelect: "none",
                                          padding: 4,
                                          margin:
                                            columnId === "list"
                                              ? "2px 0 2px 8px"
                                              : "0 0 8px 0",
                                          minHeight: "25px",
                                          backgroundColor: snapshot.isDragging
                                            ? "#FFD18B"
                                            : "#FFD18B",
                                          color: "#31506F",
                                          ...provided.draggableProps.style,
                                        }}
                                      >
                                        {item.content}
                                      </div>
                                    );
                                  }}
                                </Draggable>
                              );
                            })}
                            {provided.placeholder}
                          </div>
                        );
                      }}
                    </Droppable>
                  </div>
                );
              })}
            </DragDropContext>
          </div>

          {/* drag drop code end here */}
          <div className="row mt-2">
            <div className="d-flex justify-content-around">
              <Button variant="contained" onClick={handleSkip}>
                SKIP
              </Button>

              <Button
                variant="contained"
                onClick={handleVerify}
                color="success"
              >
                Verify
              </Button>
              <Button
                disabled={disableNext}
                variant="contained"
                onClick={handleNext}
              >
                {randomNoArray.length == 5 ? "FINISH" : "NEXT"}
              </Button>
            </div>
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            Instructions
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <ul>
              <li>
                Drag and drop The words from a sentence into respective parts of
                speech containers.
              </li>
              <li>You can drag across the containers as well.</li>
              <li>Click on the "NEXT" button to get the next sentence.</li>
              <li>Click on the "VERIFY" button to verify the dragged words.</li>
              <li>There are 5 random sentences at a time.</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MainpageMidcontent;
